import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

a = 11
b = 20
if gcd(a, b) == 1:
    frobenius_number = a * b - a - b
    print(f"GCD({a}, {b}) = {gcd(a, b)}")
    print(f"Frobenius number g({a}, {b}) = {frobenius_number}")
else:
    print("Frobenius number does not exist.")

def is_bachata_element(n):
    # Check if n = 11*a + 20*b for non-negative integers a, b
    for a in range(n // 11 + 1):
        remainder = n - 11 * a
        if remainder >= 0 and remainder % 20 == 0:
            return True
    return False

N = 100
S_min_upto_N = []
for n in range(N + 1):
    if is_bachata_element(n):
        S_min_upto_N.append(n)

print(f"Elements of S_min up to {N}: {S_min_upto_N}")
print(f"Total elements found: {len(S_min_upto_N)}")

